1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// Why the MHPCO refuses to quote a premium at all.
15	#[derive(Debug)]
16	pub enum QuoteError {
17	    /// The catalogue lists no item of this type.
18	    UnknownItemType { item_type: String },
19	}
20	
21	impl std::fmt::Display for QuoteError {
22	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
23	        match self {
24	            Self::UnknownItemType { item_type } => {
25	                write!(formatter, "the MHPCO does not insure a {item_type}")
26	            }
27	        }
28	    }
29	}
30	
31	/// Why the MHPCO refuses to settle a claim at all.
32	#[derive(Debug)]
33	pub enum ClaimError {
34	    /// The policy covers no item of this type at all.
35	    ItemNotInsured { item_type: String },
36	    /// More damages of this item type were reported than the policy covers.
37	    MoreDamagesThanInsuredItems { item_type: String },
38	}
39	
40	impl std::fmt::Display for ClaimError {
41	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
42	        match self {
43	            Self::ItemNotInsured { item_type } => {
44	                write!(formatter, "the damaged {item_type} is not insured by this policy")
45	            }
46	            Self::MoreDamagesThanInsuredItems { item_type } => write!(
47	                formatter,
48	                "more {item_type} damages were reported than the policy insures"
49	            ),
50	        }
51	    }
52	}
53	
54	/// What the MHPCO settles on a claim: the payout and the cap left on the
55	/// policy afterwards.
56	#[derive(Debug)]
57	pub struct ClaimResult {
58	    pub payout: u64,
59	    pub remaining_cap: u64,
60	}
61	
62	/// The single customer a scenario is quoted for.
63	pub struct Customer {
64	    pub years_with_mhpco: u32,
65	}
66	
67	pub struct Item {
68	    pub item_type: String,
69	    pub material: String,
70	    pub enchantment: u32,
71	    pub cursed: bool,
72	}
73	
74	const PROCESSING_FEE: u64 = 5;
75	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
76	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
77	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
78	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
79	
80	const SWORD_INSURANCE_VALUE: u64 = 1000;
81	const AMULET_INSURANCE_VALUE: u64 = 600;
82	const COMPONENT_INSURANCE_VALUE: u64 = 250;
83	const SWORD_BASE_PREMIUM: u64 = 100;
84	const AMULET_BASE_PREMIUM: u64 = 60;
85	const STAFF_BASE_PREMIUM: u64 = 80;
86	const POTION_BASE_PREMIUM: u64 = 40;
87	const COMPONENT_BASE_PREMIUM: u64 = 25;
88	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
89	const COMPONENT_BLOCK_SIZE: usize = 3;
90	const CURSE_SURCHARGE_PERCENT: u64 = 50;
91	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
92	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
93	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
94	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
95	const LOYALTY_YEARS: u32 = 2;
96	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
97	
98	/// Components, such as runes and moonstones, are the parts the MHPCO insures
99	/// alongside main items and the only items the building-block offer covers.
100	fn is_component(item: &Item) -> bool {
101	    matches!(item.item_type.as_str(), "rune" | "moonstone")
102	}
103	
104	/// The MHPCO price list: the base premium the catalogue lists for one item.
105	/// The MHPCO catalogue lists only these item types; it insures nothing else.
106	fn is_in_catalogue(item: &Item) -> bool {
107	    is_component(item) || matches!(item.item_type.as_str(), "sword" | "amulet" | "staff" | "potion")
108	}
109	
110	/// The MHPCO can only price the items its catalogue lists.
111	fn check_every_item_is_in_the_catalogue(items: &[Item]) -> Result<(), QuoteError> {
112	    match items.iter().find(|item| !is_in_catalogue(item)) {
113	        Some(unknown) => Err(QuoteError::UnknownItemType {
114	            item_type: unknown.item_type.clone(),
115	        }),
116	        None => Ok(()),
117	    }
118	}
119	
120	fn base_premium(item: &Item) -> u64 {
121	    if is_component(item) {
122	        return COMPONENT_BASE_PREMIUM;
123	    }
124	    match item.item_type.as_str() {
125	        "amulet" => AMULET_BASE_PREMIUM,
126	        "staff" => STAFF_BASE_PREMIUM,
127	        "potion" => POTION_BASE_PREMIUM,
128	        _ => SWORD_BASE_PREMIUM,
129	    }
130	}
131	
132	/// The building-block offer is reserved for a group of exactly 3 alike
133	/// components; a larger group does not qualify, it is priced per component.
134	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
135	    alike_component_count == COMPONENT_BLOCK_SIZE
136	}
137	
138	/// The price the MHPCO charges for one group of alike components: the
139	/// building-block offer when the group qualifies, otherwise per component.
140	fn component_group_base_premium(count: usize) -> u64 {
141	    if qualifies_as_building_block(count) {
142	        COMPONENT_BLOCK_BASE_PREMIUM
143	    } else {
144	        count as u64 * COMPONENT_BASE_PREMIUM
145	    }
146	}
147	
148	/// How many entries fall under each key a list of items is grouped by. The
149	/// MHPCO tallies items this way wherever a rule counts like with like: the
150	/// claim side groups by catalogue type to match damages against cover, the
151	/// premium side by alike-group key to recognise a building block.
152	fn count_by_item_type<'a>(
153	    item_types: impl Iterator<Item = &'a str>,
154	) -> BTreeMap<&'a str, usize> {
155	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
156	    for item_type in item_types {
157	        *counts.entry(item_type).or_insert(0) += 1;
158	    }
159	    counts
160	}
161	
162	/// Two components are "alike" when they share this key. For the MHPCO,
163	/// alike means the very same catalogue type: a rune and a moonstone are
164	/// never alike, so mixed component types form no building block.
165	fn alike_group_key(item: &Item) -> &str {
166	    &item.item_type
167	}
168	
169	/// The policy base premium: the sum of all insured items' base premiums,
170	/// with alike components priced per group so a block can be recognised.
171	fn policy_base_premium(items: &[Item]) -> u64 {
172	    let main_items_total: u64 = items
173	        .iter()
174	        .filter(|item| !is_component(item))
175	        .map(base_premium)
176	        .sum();
177	
178	    let alike_component_groups = count_by_item_type(
179	        items
180	            .iter()
181	            .filter(|item| is_component(item))
182	            .map(alike_group_key),
183	    );
184	
185	    main_items_total
186	        + alike_component_groups
187	            .values()
188	            .map(|count| component_group_base_premium(*count))
189	            .sum::<u64>()
190	}
191	
192	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
193	#[derive(Clone, Copy)]
194	enum Debtor {
195	    Customer,
196	    Mhpco,
197	}
198	
199	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
200	/// settles the direction by itself once it is known who owes whom: an amount
201	/// the customer owes is rounded up, an amount the office owes is rounded down.
202	/// Intermediate amounts stay fractional; only the final amount is rounded.
203	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
204	    match owed_by {
205	        Debtor::Customer => amount.ceil() as u64,
206	        Debtor::Mhpco => amount.floor() as u64,
207	    }
208	}
209	
210	/// A policy-wide modifier is measured against the policy base premium, the
211	/// sum of all item base premiums, never against a single item.
212	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
213	    policy_base_premium * percent as f64 / 100.0
214	}
215	
216	/// Every item in a quote is treated as a first insurance, so the initial
217	/// assessment surcharge is charged on the whole policy base premium.
218	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
219	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
220	}
221	
222	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
223	/// highly enchanted. This is the premium-side threshold; the claim-side
224	/// reimbursement clause judges enchantment by its own, stricter threshold.
225	fn is_highly_enchanted(item: &Item) -> bool {
226	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
227	}
228	
229	/// An item-specific risk surcharge is charged on the base premium of the
230	/// affected item, never on the policy total.
231	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
232	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
233	}
234	
235	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
236	/// item that brings two of them is surcharged for each.
237	fn item_risk_surcharge(item: &Item) -> f64 {
238	    let mut surcharge = 0.0;
239	    if item.cursed {
240	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
241	    }
242	    if is_highly_enchanted(item) {
243	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
244	    }
245	    surcharge
246	}
247	
248	/// Item-specific modifiers apply to the base premium of the affected item,
249	/// never to the policy total, so the policy owes the sum of the items' own
250	/// risk surcharges.
251	fn item_risk_surcharges(items: &[Item]) -> f64 {
252	    items.iter().map(item_risk_surcharge).sum()
253	}
254	
255	/// A long-standing customer, with at least two years of business with the
256	/// MHPCO, has earned the loyalty discount.
257	fn is_long_standing(customer: &Customer) -> bool {
258	    customer.years_with_mhpco >= LOYALTY_YEARS
259	}
260	
261	/// The loyalty discount is a policy-wide modifier, so it is measured against
262	/// the policy base premium.
263	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
264	    if is_long_standing(customer) {
265	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
266	    } else {
267	        0.0
268	    }
269	}
270	
271	/// A contract is a follow-up when the customer already holds at least one
272	/// other contract with the MHPCO; the customer's very first is not.
273	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
274	    contracts_already_held > 0
275	}
276	
277	/// Every contract after the customer's first earns the follow-up discount. It
278	/// is a policy-wide modifier, so it is measured against the policy base premium.
279	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
280	    if is_follow_up_contract(contracts_already_held) {
281	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
282	    } else {
283	        0.0
284	    }
285	}
286	
287	/// What the customer's standing with the MHPCO adds to or takes off the policy
288	/// base premium: the net of every policy-wide surcharge and discount. Positive
289	/// amounts raise the premium, negative amounts lower it.
290	fn policy_wide_modifiers(
291	    customer: &Customer,
292	    contracts_already_held: u32,
293	    policy_base_premium: f64,
294	) -> f64 {
295	    first_insurance_surcharge(policy_base_premium)
296	        - loyalty_discount(customer, policy_base_premium)
297	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
298	}
299	
300	/// The premium the policy earns before the processing fee: the policy base
301	/// premium, plus what the items' own risks cost, plus what the customer's
302	/// standing adjusts.
303	fn modified_policy_premium(
304	    customer: &Customer,
305	    contracts_already_held: u32,
306	    items: &[Item],
307	) -> f64 {
308	    let policy_base_premium = policy_base_premium(items) as f64;
309	    policy_base_premium
310	        + item_risk_surcharges(items)
311	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
312	}
313	
314	/// The MHPCO adds its processing fee to every premium at the very end, after
315	/// every surcharge and discount has been settled.
316	pub fn quote_premium(
317	    customer: &Customer,
318	    contracts_already_held: u32,
319	    items: &[Item],
320	) -> Result<u64, QuoteError> {
321	    check_every_item_is_in_the_catalogue(items)?;
322	    Ok(rounded_in_mhpco_favor(
323	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
324	        Debtor::Customer,
325	    ))
326	}
327	
328	/// Damage to a very highly enchanted item is reimbursed at only half the
329	/// damage amount. This claim-side threshold is deliberately stricter than, and
330	/// separate from, the premium-side high-enchantment risk surcharge: an item can
331	/// be enchanted enough to cost more to insure yet not enough to be halved.
332	fn is_reimbursed_by_half(item: &Item) -> bool {
333	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
334	}
335	
336	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
337	/// before the deductible is taken off. Full reimbursement is the MHPCO's
338	/// standing position: it is both what an item with no clause receives and what
339	/// the dragon-material clause prescribes, so that clause asks for no share of
340	/// its own. Only the halving clause departs from full reimbursement, and it
341	/// wins wherever it applies.
342	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
343	    if is_reimbursed_by_half(damaged_item) {
344	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
345	    } else {
346	        damage.amount as f64
347	    }
348	}
349	
350	/// The deductible applies per damage event, after the reimbursement clauses.
351	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
352	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
353	}
354	
355	/// Which insured item a reported damage refers to. A damage names only a
356	/// catalogue type, so the policy is searched for an item of that type; the
357	/// reimbursement clauses are judged against the item found here, not the report.
358	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
359	    items
360	        .iter()
361	        .find(|item| item.item_type == damage.item_type)
362	        .expect("the damaged item is insured by this policy")
363	}
364	
365	/// What the MHPCO owes for an incident filed against a policy: the sum of the
366	/// reimbursements its damages earn, rounded in the office's favor at the end.
367	pub fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
368	    let total: f64 = incident
369	        .damages
370	        .iter()
371	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
372	        .sum();
373	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
374	}
375	
376	/// The MHPCO price list also lists what each item is insured for.
377	fn insurance_value(item: &Item) -> u64 {
378	    if is_component(item) {
379	        return COMPONENT_INSURANCE_VALUE;
380	    }
381	    match item.item_type.as_str() {
382	        "amulet" => AMULET_INSURANCE_VALUE,
383	        _ => SWORD_INSURANCE_VALUE,
384	    }
385	}
386	
387	/// The insurance sum of a policy is the sum of its items' insurance values.
388	fn insurance_sum(items: &[Item]) -> u64 {
389	    items.iter().map(insurance_value).sum()
390	}
391	
392	/// The total payout per policy is capped at twice the insurance sum.
393	fn policy_cap(items: &[Item]) -> u64 {
394	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
395	}
396	
397	/// How the cap limits one settlement: the MHPCO pays what the incident earned,
398	/// but never more than the cap the policy has left, and reports the cap that
399	/// survives the payout.
400	fn settled_within_cap(earned: u64, available_cap: u64) -> ClaimResult {
401	    let payout = earned.min(available_cap);
402	    ClaimResult {
403	        payout,
404	        remaining_cap: available_cap - payout,
405	    }
406	}
407	
408	/// How much of its cap a policy still has to pay out with, once earlier claims
409	/// have drawn on it. A cap can be drawn down until it is exhausted, and an
410	/// exhausted cap is simply nothing left, never a debt the policy owes back.
411	fn cap_remaining_on(items: &[Item], cap_already_consumed: u64) -> u64 {
412	    policy_cap(items).saturating_sub(cap_already_consumed)
413	}
414	
415	/// How many items of a catalogue type a policy insures. A type the policy never
416	/// mentions is insured none of: the MHPCO holds no cover for what it did not
417	/// write down.
418	fn insured_count_of(insured_counts: &BTreeMap<&str, usize>, item_type: &str) -> usize {
419	    insured_counts.get(item_type).copied().unwrap_or(0)
420	}
421	
422	/// Every reported damage must be covered by an insured item of its own. The
423	/// office compares the damages it was sent against the policy type by type, so a
424	/// type damaged twice needs two insured items of that type to stand. One
425	/// comparison decides admissibility; how far it falls short decides which
426	/// refusal the claim earns -- a type the policy does not cover at all is refused
427	/// as uninsured, a type covered by too few items as an over-count.
428	fn check_policy_covers_every_damage(
429	    items: &[Item],
430	    incident: &Incident,
431	) -> Result<(), ClaimError> {
432	    let insured = count_by_item_type(items.iter().map(|item| item.item_type.as_str()));
433	    for (item_type, reported) in
434	        count_by_item_type(incident.damages.iter().map(|damage| damage.item_type.as_str()))
435	    {
436	        let insured_of_that_type = insured_count_of(&insured, item_type);
437	        if insured_of_that_type == 0 {
438	            return Err(ClaimError::ItemNotInsured {
439	                item_type: item_type.to_string(),
440	            });
441	        }
442	        if reported > insured_of_that_type {
443	            return Err(ClaimError::MoreDamagesThanInsuredItems {
444	                item_type: item_type.to_string(),
445	            });
446	        }
447	    }
448	    Ok(())
449	}
450	
451	/// What the MHPCO settles on an incident filed against a policy: what the
452	/// incident earns, limited by the cap the policy has left. The office first
453	/// satisfies itself that the claim is admissible at all; an inadmissible claim
454	/// is refused whole, and nothing is paid out on it.
455	pub fn claim(
456	    items: &[Item],
457	    incident: &Incident,
458	    cap_already_consumed: u64,
459	) -> Result<ClaimResult, ClaimError> {
460	    check_policy_covers_every_damage(items, incident)?;
461	    Ok(settled_within_cap(
462	        claim_payout(items, incident),
463	        cap_remaining_on(items, cap_already_consumed),
464	    ))
465	}
466	
467	#[cfg(test)]
468	mod tests {
469	    use super::*;
470	
471	    /// A customer with the given number of years of business with the MHPCO,
472	    /// the standing the loyalty discount is judged against.
473	    fn customer_of(years_with_mhpco: u32) -> Customer {
474	        Customer { years_with_mhpco }
475	    }
476	
477	    /// A customer in their first year of business with the MHPCO.
478	    fn newcomer() -> Customer {
479	        customer_of(0)
480	    }
481	
482	    /// A plain, unenchanted, uncursed item of the given catalogue type.
483	    fn plain(item_type: &str) -> Item {
484	        Item {
485	            item_type: item_type.to_string(),
486	            material: "steel".to_string(),
487	            enchantment: 0,
488	            cursed: false,
489	        }
490	    }
491	
492	    /// How many contracts the customer already holds when a quote is made: the
493	    /// standing the follow-up contract discount is judged against. The very
494	    /// first contract earns no discount; every later one does.
495	    const FIRST_CONTRACT: u32 = 0;
496	    const SECOND_CONTRACT: u32 = 1;
497	    const THIRD_CONTRACT: u32 = 2;
498	
499	    /// A group of `count` alike components, the shape the building-block
500	    /// offer is judged against.
501	    fn alike(count: usize, item_type: &str) -> Vec<Item> {
502	        (0..count).map(|_| plain(item_type)).collect()
503	    }
504	
505	    /// An incident reporting one damage per `(item type, amount)` pair, the
506	    /// shape a claim is filed as: the deductible is judged per damage entry,
507	    /// so each pair stands for one damage event.
508	    fn incident_of(damages: &[(&str, i64)]) -> Incident {
509	        Incident {
510	            damages: damages
511	                .iter()
512	                .map(|(item_type, amount)| Damage {
513	                    item_type: item_type.to_string(),
514	                    amount: *amount,
515	                })
516	                .collect(),
517	        }
518	    }
519	
520	    /// What the MHPCO pays when a policy covering just `item` is hit by a
521	    /// single damage of `amount` to that item: the shape every reimbursement
522	    /// clause example is stated in, so each test shows only the item trait the
523	    /// clause turns on and the payout it earns.
524	    fn payout_for_single_damage(item: Item, amount: i64) -> u64 {
525	        let item_type = item.item_type.clone();
526	        claim_payout(&[item], &incident_of(&[(&item_type, amount)]))
527	    }
528	
529	    /// How the MHPCO settles a claim: a payout and the cap the policy has left
530	    /// afterwards are one settlement, so a claim example states both together.
531	    fn assert_settles(result: &ClaimResult, payout: u64, remaining_cap: u64) {
532	        assert_eq!(result.payout, payout);
533	        assert_eq!(result.remaining_cap, remaining_cap);
534	    }
535	
536	    // ---- Base premiums: price list (one test per catalogue entry) ----
537	
538	    #[test]
539	    fn quotes_empty_item_list_as_processing_fee_only() {
540	        assert_eq!(quote_premium(&newcomer(), FIRST_CONTRACT, &[]).expect("the quote is priced"), 5);
541	    }
542	
543	    #[test]
544	    fn quotes_plain_sword_base_premium_of_100() {
545	        assert_eq!(quote_premium(&newcomer(), FIRST_CONTRACT, &[plain("sword")]).expect("the quote is priced"), 115);
546	    }
547	
548	    #[test]
549	    fn quotes_plain_amulet_base_premium_of_60() {
550	        assert_eq!(quote_premium(&newcomer(), FIRST_CONTRACT, &[plain("amulet")]).expect("the quote is priced"), 71);
551	    }
552	
553	    #[test]
554	    fn quotes_plain_staff_base_premium_of_80() {
555	        assert_eq!(quote_premium(&newcomer(), FIRST_CONTRACT, &[plain("staff")]).expect("the quote is priced"), 93);
556	    }
557	
