python3 - <<'EOF'
import re
p='src/lib.rs'
s=open(p).read()

old_base = '''fn base_premium(item: &Item) -> u64 {
    if is_component(item) {
        return COMPONENT_BASE_PREMIUM;
    }
    match item.item_type.as_str() {
        "amulet" => AMULET_BASE_PREMIUM,
        "staff" => STAFF_BASE_PREMIUM,
        "potion" => POTION_BASE_PREMIUM,
        _ => SWORD_BASE_PREMIUM,
    }
}'''
new_base = '''fn base_premium(item: &Item) -> u64 {
    if is_component(item) {
        return COMPONENT_BASE_PREMIUM;
    }
    match item.item_type.as_str() {
        "sword" => SWORD_BASE_PREMIUM,
        "amulet" => AMULET_BASE_PREMIUM,
        "staff" => STAFF_BASE_PREMIUM,
        "potion" => POTION_BASE_PREMIUM,
        other => panic!("the catalogue lists no base premium for a {other}"),
    }
}'''
assert old_base in s
s=s.replace(old_base,new_base)
open(p,'w').write(s)
EOF
cargo test 2>&1 | tail -4; cargo clippy 2>&1 | tail -4

